export class Money {
  private constructor(readonly amountCents: number, readonly currency: string) {}

  static of(amountCents: number, currency: string): Money {
    if (!Number.isInteger(amountCents) || amountCents < 0) throw new RangeError("amount");
    return Object.freeze(new Money(amountCents, currency));
  }

  equals(other: Money): boolean {
    return this.amountCents === other.amountCents && this.currency === other.currency;
  }
}
